     3	读取 payout-service 导出的订单 JSON, 按 amount 汇总账目.
     4	生产上这份 JSON 由 payout-service 的 scripts/dump_orders.py 生成.
     5	{
     6	  "name": "orders-consumer",
     7	  "version": "0.9.2",
     8	  "type": "module",
     9	  "private": true
    10	}
    11	#!/usr/bin/env bash
    12	# 消费者跑法: 读 payout-service 导出的订单 JSON.
    13	set -euo pipefail
    14	node "$(dirname "$0")/ledger.js" "$1"
    15	import fs from "node:fs";
    16	
    17	const rows = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
    18	let total = 0;
    19	const missing = [];
    20	for (const row of rows) {
    21	  if (row.amount === null) {
    22	    missing.push(row.id);
    23	    continue;
    24	  }
    25	  total += Number(row.amount);
    26	}
    27	console.log(JSON.stringify({ total, missing }, null, 2));
